                jacobian[i] = new double[n];
                jacobian[i][0] = 0;
                for (int j = 1; j < (n - 1); ++j) {
                    if (i == 0) {
                        jacobian[i][j] = 0;
                    } else if (i != (m - 1)) {
                        jacobian[i][j] = i * (j + 1);
                    } else {
                        jacobian[i][j] = 0;
