x2[i][0] = x[i][0];
x2[i][1] = x[i][0];
x2[i][2] = x[i][1];
x2[i][3] = x[i][2];
x2[i][4] = x[i][1];
x2[i][5] = x[i][3];
x2[i][6] = x[i][2];
