ac = ac + ((bc + ad) >>> 32);
bita = (prodB & 0x8000000000000000L) != 0;
bitb = (ac & 0x8000000000000000L ) != 0;
prodB += ac;
bitsum = (prodB & 0x8000000000000000L) != 0;
/* Carry */
if ( (bita && bitb) ||
((bita || bitb) && !bitsum) ) {
prodA++;
}
/* Multiply by shpi0 */
c = shpi0 >>> 32;
d = shpi0 & 0xffffffffL;
bd = b * d;
bc = b * c;
ad = a * d;
prodA += bd + ((bc + ad) << 32);
