return y; // return +/- 0.0
} else {
return copySign(Math.PI, y);
}
}
if (x < 0 || invx < 0) {
if (y < 0 || invy < 0) {
return -Math.PI;
} else {
return Math.PI;
}
} else {
return result;
}
}
