Assert.assertEquals(new Fraction(0), m.getEntry(i, columns - 1));
}
for (int j = 0; j < columns; ++j) {
Assert.assertEquals(new Fraction(0), m.getEntry(0, j));
Assert.assertEquals(new Fraction(0), m.getEntry(rows - 1, j));
