result.shiftLeft();
final int r = rl * RADIX; // compute the next digit and put it in
final int rh = r / divisor;
rl = r - rh * divisor;
result.mant[0] = rh;
}
final int excp = result.round(rl * RADIX / divisor); // do the rounding
if (excp != 0) {
result = dotrap(excp, DIVIDE_TRAP, result, result);
}
