int index = 0;
for (int i = 0; i < rows; i++) {
WeightedMeasurement wm = measurements[i];
double factor = -FastMath.sqrt(wm.getWeight());
for (int j = 0; j < cols; ++j) {
jacobian[index++] = factor * wm.getPartial(parameters[j]);
}
}
}
