if (xabs>x3max) {
double r=x3max/xabs;
s3=1.0+s3*r*r;
x3max=xabs;
} else {
if (xabs!=0.0) {
double r=xabs/x3max;
s3+=r*r;
}
}
}
} else {
s2+=xabs*xabs;
}
}
double norm;
if (s1!=0.0) {
norm = x1max*Math.sqrt(s1+(s2/x1max)/x1max);
} else {
if (s2==0.0) {
norm = x3max*Math.sqrt(s3);
} else {
if (s2>=x3max) {
norm = Math.sqrt(s2*(1.0+(x3max/s2)*(x3max*s3)));
} else {
norm = Math.sqrt(x3max*((s2/x3max)+(x3max*s3)));
}
}
}
return norm;
}

