result.shiftLeft();
if (i == 0) {
result.mant[0] = aextradigit+bextradigit;
aextradigit = 0;
bextradigit = 0;
}
}
/* result is zero if after normalization the most sig. digit is zero */
if (result.mant[mant.length-1] == 0) {
