final double pib = 6.123233995736766E-17 * 2;
za = pia - result;
zb = -(za - pia + result);
zb += pib - resultb;
result = za + zb;
resultb = -(result - za - zb);
}
if (negate ^ leftPlane) {
result = -result;
}
return result;
