switch (allowedSolution) {
case ANY_SIDE :
return absYA.lessThan(absYB) ? xA : xB;
case LEFT_SIDE :
return xA;
case RIGHT_SIDE :
return xB;
case BELOW_SIDE :
return yA.lessThan(zero) ? xA : xB;
case ABOVE_SIDE :
return yA.lessThan(zero) ? xB : xA;
default :
