 public double evaluate(final double[] values, final int begin, final int length, final double p) {
test(values, begin, length);
if ((p > 100) || (p <= 0)) {
throw new IllegalArgumentException("invalid quantile value: " + p);
}
if (length == 0) {
return Double.NaN;
}
if (length == 1) {
return values[begin]; // always return single value for n = 1
}
double n = (double) length;
double pos = p * (n + 1) / 100;
double fpos = Math.floor(pos);
int intPos = (int) fpos;
double dif = pos - fpos;
double[] sorted = new double[length];
System.arraycopy(values, begin, sorted, 0, length);
Arrays.sort(sorted);
if (pos < 1) {
return sorted[0];
}
if (pos >= n) {
return sorted[length - 1];
}
double lower = sorted[intPos - 1];
double upper = sorted[intPos];
return lower + dif * (upper - lower);
}
/**
* Returns the value of the quantile field (determines what percentile is
* computed when evaluate() is called with no quantile argument).
* * @return quantile
*/

 public double getQuantile() {
return quantile;
}
/**
* Sets the value of the quantile field (determines what percentile is * computed when evaluate() is called with no quantile argument).
* * @param p a value between 0 < p <= 100 * @throws IllegalArgumentException if p is not greater than 0 and less
* than or equal to 100
*/

 public void setQuantile(final double p) {
if (p <= 0 || p > 100) {
throw new IllegalArgumentException("Illegal quantile value: " + p);
}
quantile = p;
}

