 public void clear() {
cachedNormalDeviate = Double.NaN;
}

/**
* Sets the seed of the underyling random number generator using a * <code>long</code> seed. Sequences of values generated starting with the
* same seeds should be identical.
* <p>
* Implementations that do not override the default implementation of * <code>nextGaussian</code> should include a call to {@link #clear} in the
* implementation of this method.</p>
*
* @param seed the seed value
*/

 public void nextBytes(byte[] bytes) {
int bytesOut = 0;
while (bytesOut < bytes.length) {
int randInt = nextInt();
for (int i = 0; i < 3; i++) {
if ( i > 0) {
randInt = randInt >> 8;
}
bytes[bytesOut++] = (byte) randInt;
if (bytesOut == bytes.length) {
return;
}
}
}
}
/**
* Returns the next pseudorandom, uniformly distributed <code>int</code>
* value from this random number generator's sequence. * All 2<font size="-1"><sup>32</sup></font> possible <tt>int</tt> values
* should be produced with (approximately) equal probability. * <p>
* The default implementation provided here returns * <pre>
* <code>(int) (nextDouble() * Integer.MAX_VALUE)</code>
* </pre></p>
*
* @return the next pseudorandom, uniformly distributed <code>int</code>
* value from this random number generator's sequence
*/

 public int nextInt(int n) {
if (n <= 0 ) {
throw new IllegalArgumentException("upper bound must be positive");
}
int result = (int) (nextDouble() * n);
return result < n ? result : n - 1;
}
/**
* Returns the next pseudorandom, uniformly distributed <code>long</code>
* value from this random number generator's sequence. All * 2<font size="-1"><sup>64</sup></font> possible <tt>long</tt> values * should be produced with (approximately) equal probability. * <p> * The default implementation returns * <pre>
* <code>(long) (nextDouble() * Long.MAX_VALUE)</code>
* </pre></p>
*
* @return the next pseudorandom, uniformly distributed <code>long</code>
*value from this random number generator's sequence
*/

 public long nextLong() {
return (long) (nextDouble() * Long.MAX_VALUE);
}
/**
* Returns the next pseudorandom, uniformly distributed
* <code>boolean</code> value from this random number generator's
* sequence. * <p> * The default implementation returns * <pre>
* <code>nextDouble() <= 0.5</code>
* </pre></p>
* * @return the next pseudorandom, uniformly distributed
* <code>boolean</code> value from this random number generator's
* sequence
*/

 public float nextFloat() {
return (float) nextDouble();
}
/**
* Returns the next pseudorandom, uniformly distributed * <code>double</code> value between <code>0.0</code> and
* <code>1.0</code> from this random number generator's sequence. * <p>
* This method provides the underlying source of random data used by the
* other methods.</p> *
* @return the next pseudorandom, uniformly distributed * <code>double</code> value between <code>0.0</code> and
* <code>1.0</code> from this random number generator's sequence
*/

 public double nextGaussian() {
if (!Double.isNaN(cachedNormalDeviate)) {
double dev = cachedNormalDeviate;
cachedNormalDeviate = Double.NaN;
return dev;
}
double v1 = 0;
double v2 = 0;
double s = 1;
while (s >=1 ) { v1 = 2 * nextDouble() - 1; v2 = 2 * nextDouble() - 1; s = v1 * v1 + v2 * v2;
}
if (s != 0) {
s = Math.sqrt(-2 * Math.log(s) / s); }
cachedNormalDeviate = v2 * s;
return v1 * s; }

