      while (iMax - iMin > 5) {

        // use the last estimated index as the splitting index
        StepInterpolator si = (StepInterpolator) steps.get(index);
        int location = locatePoint(time, si);
        if (location < 0) {
          iMax = index;
          tMax = 0.5 * (si.getPreviousTime() + si.getCurrentTime());
        } else if (location > 0) {
          iMin = index;
