        }

        // force the next size reduction to be at least one tenth
        int low  = Math.max(iMin + 1, (9 * iMin + iMax) / 10);
        int high = Math.min(iMax - 1, (iMin + 9 * iMax) / 10);
        if (index < low) {
          index = low;
        } else if (index > high) {
          index = high;
        }

      }

