outDataRow[col] = dataRow[col] + mRow[col];
}
}
return new Array2DRowRealMatrix(outData, false);
}
/** {@inheritDoc} */
@Override

 public Array2DRowRealMatrix subtract(final Array2DRowRealMatrix m)
throws IllegalArgumentException {
// safety check
