 public void addValue(double v) {
if (windowSize != INFINITE_WINDOW) {
if (getN() == windowSize) {
eDA.addElementRolling(v);
} else if (getN() < windowSize) {
eDA.addElement(v);
}
} else {
eDA.addElement(v);
}
}
/**
* Removes the most recent value from the dataset.
*/

 public void removeMostRecentValue() {
eDA.discardMostRecentElements(1);
}
/**
* Replaces the most recently stored value with the given value.
* There must be at least one element stored to call this method.
* * @param v the value to replace the most recent stored value
* @return replaced value
*/

 public double replaceMostRecentValue(double v) {
return eDA.substituteMostRecentElement(v);
}
/** * Returns the <a href="http://www.xycoon.com/arithmetic_mean.htm">
* arithmetic mean </a> of the available values * @return The mean or Double.NaN if no values have been added.
*/

 public double getMean() {
return apply(meanImpl);
}
/** * Returns the <a href="http://www.xycoon.com/geometric_mean.htm">
* geometric mean </a> of the available values
* @return The geometricMean, Double.NaN if no values have been added, * or if the product of the available values is less than or equal to 0.
*/

 public double getGeometricMean() {
return apply(geometricMeanImpl);
}
/** * Returns the variance of the available values.
* @return The variance, Double.NaN if no values have been added * or 0.0 for a single value set. */

 public double getVariance() {
return apply(varianceImpl);
}
/** * Returns the standard deviation of the available values.
* @return The standard deviation, Double.NaN if no values have been added * or 0.0 for a single value set. */

 public double getStandardDeviation() {
double stdDev = Double.NaN;
if (getN() > 0) {
if (getN() > 1) {
stdDev = Math.sqrt(getVariance());
} else {
stdDev = 0.0;
}
}
return (stdDev);
}
/**
* Returns the skewness of the available values. Skewness is a * measure of the asymmetry of a given distribution.
* @return The skewness, Double.NaN if no values have been added * or 0.0 for a value set &lt;=2. */

 public double getSkewness() {
return apply(skewnessImpl);
}
/**
* Returns the Kurtosis of the available values. Kurtosis is a * measure of the "peakedness" of a distribution
* @return The kurtosis, Double.NaN if no values have been added, or 0.0 * for a value set &lt;=3. */

 public double getKurtosis() {
return apply(kurtosisImpl);
}
/** * Returns the maximum of the available values
* @return The max or Double.NaN if no values have been added.
*/

 public double getMax() {
return apply(maxImpl);
}
/** * Returns the minimum of the available values
* @return The min or Double.NaN if no values have been added.
*/

 public double getMin() {
return apply(minImpl);
}
/** * Returns the number of available values
* @return The number of available values
*/

 public long getN() {
return eDA.getNumElements();
}
/**
* Returns the sum of the values that have been added to Univariate.
* @return The sum or Double.NaN if no values have been added
*/

 public double getSum() {
return apply(sumImpl);
}
/**
* Returns the sum of the squares of the available values.
* @return The sum of the squares or Double.NaN if no * values have been added.
*/

 public double getSumsq() {
return apply(sumsqImpl);
}
/** * Resets all statistics and storage
*/

 public void clear() {
eDA.clear();
}
/**
* Returns the maximum number of values that can be stored in the
* dataset, or INFINITE_WINDOW (-1) if there is no limit.
* * @return The current window size or -1 if its Infinite.
*/

 public int getWindowSize() {
return windowSize;
}
/**
* WindowSize controls the number of values which contribute * to the reported statistics. For example, if * windowSize is set to 3 and the values {1,2,3,4,5} * have been added <strong> in that order</strong> * then the <i>available values</i> are {3,4,5} and all
* reported statistics will be based on these values
* @param windowSize sets the size of the window.
*/

 public void setWindowSize(int windowSize) {
if (windowSize < 1) {
if (windowSize != INFINITE_WINDOW) {
throw MathRuntimeException.createIllegalArgumentException(
"window size must be positive ({0})", windowSize);
}
}

this.windowSize = windowSize;
// We need to check to see if we need to discard elements
// from the front of the array. If the windowSize is less than // the current number of elements.
if (windowSize != INFINITE_WINDOW && windowSize < eDA.getNumElements()) {
eDA.discardFrontElements(eDA.getNumElements() - windowSize);
}
}

/**
* Returns the current set of values in an array of double primitives. * The order of addition is preserved. The returned array is a fresh
* copy of the underlying data -- i.e., it is not a reference to the
* stored data.
* * @return returns the current set of numbers in the order in which they * were added to this set
*/

 public double[] getValues() {
return eDA.getElements();
}
/**
* Returns the current set of values in an array of double primitives, * sorted in ascending order. The returned array is a fresh
* copy of the underlying data -- i.e., it is not a reference to the
* stored data.
* @return returns the current set of * numbers sorted in ascending order */

 public double[] getSortedValues() {
double[] sort = getValues();
Arrays.sort(sort);
return sort;
}
/**
* Returns the element at the specified index
* @param index The Index of the element
* @return return the element at the specified index
*/

 public double getPercentile(double p) {
if (percentileImpl instanceof Percentile) {
((Percentile) percentileImpl).setQuantile(p);
} else {
try {
percentileImpl.getClass().getMethod("setQuantile", new Class[] {Double.TYPE}).invoke(percentileImpl,
new Object[] {Double.valueOf(p)});
} catch (NoSuchMethodException e1) { // Setter guard should prevent
throw MathRuntimeException.createIllegalArgumentException(
"percentile implementation {0} does not support setQuantile",
percentileImpl.getClass().getName());
} catch (IllegalAccessException e2) {
throw MathRuntimeException.createIllegalArgumentException(
"cannot access setQuantile method in percentile implementation {0}",
percentileImpl.getClass().getName());
} catch (InvocationTargetException e3) {
throw MathRuntimeException.createIllegalArgumentException(e3.getCause()); }
}
return apply(percentileImpl);
}

/**
* Generates a text report displaying univariate statistics from values
* that have been added. Each statistic is displayed on a separate
* line.
* * @return String with line feeds displaying statistics
*/
@Override

 public String toString() {
StringBuffer outBuffer = new StringBuffer();
String endl = "\n";
outBuffer.append("DescriptiveStatistics:").append(endl);
outBuffer.append("n: ").append(getN()).append(endl);
outBuffer.append("min: ").append(getMin()).append(endl);
outBuffer.append("max: ").append(getMax()).append(endl);
outBuffer.append("mean: ").append(getMean()).append(endl);
outBuffer.append("std dev: ").append(getStandardDeviation())
.append(endl);
outBuffer.append("median: ").append(getPercentile(50)).append(endl);
outBuffer.append("skewness: ").append(getSkewness()).append(endl);
outBuffer.append("kurtosis: ").append(getKurtosis()).append(endl);
return outBuffer.toString();
}

/**
* Apply the given statistic to the data associated with this set of statistics.
* @param stat the statistic to apply
* @return the computed value of the statistic.
*/

 public double apply(UnivariateStatistic stat) {
return stat.evaluate(eDA.getInternalValues(), eDA.start(), eDA.getNumElements());
}
