    public Complex tan() {
        if (isNaN()) {
            return Complex.NaN;
        }

        double real2 = 2.0 * real;
        double imaginary2 = 2.0 * imaginary;
        double d = Math.cos(real2) + MathUtils.cosh(imaginary2);

        return createComplex(Math.sin(real2) / d, MathUtils.sinh(imaginary2) / d);
