 public double abs() {
if (isNaN()) {
return Double.NaN;
}

if (isInfinite()) {
return Double.POSITIVE_INFINITY;
}

if (Math.abs(real) < Math.abs(imaginary)) {
if (imaginary == 0.0) {
return Math.abs(real);
}
double q = real / imaginary;
return (Math.abs(imaginary) * Math.sqrt(1 + q*q));
} else {
if (real == 0.0) {
return Math.abs(imaginary);
}
double q = imaginary / real;
return (Math.abs(real) * Math.sqrt(1 + q*q));
}
}

/**
* Return the sum of this complex number and the given complex number.
* <p>
* Uses the definitional formula * <pre>
* (a + bi) + (c + di) = (a+c) + (b+d)i
* </pre></p>
* <p>
* If either this or <code>rhs</code> has a NaN value in either part,
* {@link #NaN} is returned; otherwise Inifinite and NaN values are
* returned in the parts of the result according to the rules for
* {@link java.lang.Double} arithmetic.</p> *
* @param rhs the other complex number
* @return the complex number sum
* @throws NullPointerException if <code>rhs</code> is null
*/

 public Complex divide(Complex rhs) {
if (isNaN() || rhs.isNaN()) {
return NaN;
}
double c = rhs.getReal();
double d = rhs.getImaginary();
if (c == 0.0 && d == 0.0) {
return NaN;
}

if (rhs.isInfinite() && !isInfinite()) {
return ZERO;
}
if (Math.abs(c) < Math.abs(d)) {
if (d == 0.0) {
return createComplex(real/c, imaginary/c);
}
double q = c / d;
double denominator = c * q + d;
return createComplex((real * q + imaginary) / denominator,
(imaginary * q - real) / denominator);
} else {
if (c == 0.0) {
return createComplex(imaginary/d, -real/c);
}
double q = d / c;
double denominator = d * q + c;
return createComplex((imaginary * q + real) / denominator,
(imaginary - real * q) / denominator);
}
}

/**
* Test for the equality of two Complex objects.
* <p>
* If both the real and imaginary parts of two Complex numbers
* are exactly the same, and neither is <code>Double.NaN</code>, the two
* Complex objects are considered to be equal.</p>
* <p>
* All <code>NaN</code> values are considered to be equal - i.e, if either
* (or both) real and imaginary parts of the complex number are equal
* to <code>Double.NaN</code>, the complex number is equal to * <code>Complex.NaN</code>.</p>
*
* @param other Object to test for equality to this
* @return true if two Complex objects are equal, false if
* object is null, not an instance of Complex, or
* not equal to this Complex instance
* */
@Override

 public boolean equals(Object other) {
boolean ret;

if (this == other) { ret = true;
} else if (other == null) {
ret = false;
} else {
try {
Complex rhs = (Complex)other;
if (rhs.isNaN()) {
ret = this.isNaN();
} else {
ret = (real == rhs.real) && (imaginary == rhs.imaginary); }
} catch (ClassCastException ex) {
// ignore exception
ret = false;
}
}

return ret;
}

