/** extracts the l and u matrices from compact lu representation */
protected void splitLU(RealMatrix lu, double[][] lowerData, double[][] upperData) throws InvalidMatrixException { if (!lu.isSquare() || lowerData.length != lowerData[0].length || upperData.length != upperData[0].length ||
lowerData.length != upperData.length
|| lowerData.length != lu.getRowDimension()) {
throw new InvalidMatrixException("incorrect dimensions");
} int n = lu.getRowDimension();
for (int i = 0; i < n; i++) {
for (int j = 0; j < n; j++) {
if (j < i) {
lowerData[i][j] = lu.getEntry(i, j);
upperData[i][j] = 0d;
} else if (i == j) {
lowerData[i][j] = 1d;
upperData[i][j] = lu.getEntry(i, j);
} else {
lowerData[i][j] = 0d;
upperData[i][j] = lu.getEntry(i, j);
} }
}
}

/** Returns the result of applying the given row permutation to the matrix */
protected RealMatrix permuteRows(RealMatrix matrix, int[] permutation) {
if (!matrix.isSquare() || matrix.getRowDimension() != permutation.length) {
throw new IllegalArgumentException("dimension mismatch");
}
int n = matrix.getRowDimension();
int m = matrix.getColumnDimension();
double out[][] = new double[m][n];
for (int i = 0; i < n; i++) {
for (int j = 0; j < m; j++) {
out[i][j] = matrix.getEntry(permutation[i], j);
}
}
return new Array2DRowRealMatrix(out);
}

