import junit.framework.*;

public class DormandPrince54IntegratorTest
  extends TestCase {

  public DormandPrince54IntegratorTest(String name) {
    super(name);
  }

  public void testDimensionCheck() {
    try  {
      TestProblem1 pb = new TestProblem1();
