createFile(theFile, fileSizes[i]);
}
Iterator files = FileUtils.iterateFiles(subDir,
new WildcardFileFilter("*.*"),
new WildcardFileFilter("*"));
Map foundFileNames = new HashMap();
while (files.hasNext()) {
