in = new InputStreamReader(new FileInputStream(file));
List lines = IOUtils.readLines(in);
assertEquals(Arrays.asList(data), lines);
assertEquals(-1, in.read());
} finally {
IOUtils.closeQuietly(in);
deleteFile(file);
}
}

