* @throws IOException if an I/O error occurs
* @since Commons IO 1.1
*/

 public static char[] toCharArray(Reader input) throws IOException {
CharArrayWriter sw = new CharArrayWriter();
copy(input, sw);
return sw.toCharArray();
}
